SELECT id,tenant_key,company_id,sample_order_id,review_date,result,opinion,create_by,create_time,update_by,update_time
FROM dev_sample_review WHERE tenant_key=#{tenant} AND company_id=#{companyId}

    AND sample_order_id IN #{id}
AND false
ORDER BY sample_order_id,id LIMIT 101

SELECT tenant_key,company_id,review_id,user_id,seq FROM dev_sample_reviewer
WHERE tenant_key=#{tenant} AND company_id=#{companyId}

    AND review_id IN #{id}
AND false
ORDER BY review_id,seq,user_id LIMIT 10001
